     (mass[MW]^4*(mass[MW]^2 - mass[MZ]^2)) + 
    mtad[{mass[MZ], mass[MW], 0}, {1, 1, 0}]/
     (mass[MZ]^4*(-mass[MW]^2 + mass[MZ]^2)) + 
    mtad[{mass[MZ], mass[MW], mass[MZ]}, {1, 1, 1}]/
     (mass[MZ]^2*(-mass[MW]^2 + mass[MZ]^2))))/(576*cw^2*(-2 + d + d^2)*Pi^8*
   sw^2)
